export async function listTools() {
  return [
    {
      name: 'download_asset',
      description: 'Download a binary asset by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          asset_id: { type: 'string', description: 'The id of the asset to download.' },
        },
        required: ['asset_id'],
        additionalProperties: false,
