}

export async function callTool(name, args = {}) {
  if (name !== 'download_asset') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32601;
    throw err;
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw invalidParams('Arguments must be an object');
  }

  const allowed = new Set(['asset_id']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw invalidParams('Unknown argument: ' + key);
    }
  }

  if (!('asset_id' in args)) {
    throw invalidParams('Missing required argument: asset_id');
  }

  const assetId = args.asset_id;
  if (typeof assetId !== 'string') {
    throw invalidParams('asset_id must be a string');
  }

  const asset = ASSETS[assetId];
  if (!asset) {
    throw invalidParams('Unknown asset: ' + assetId);
  }

  return {
    content: [
      {
        type: 'resource',
        resource: {
          uri: asset.uri,
          mimeType: asset.mimeType,
          blob: asset.blob,
        },
      },
    ],
  };
}
```

